#!/usr/bin/env bash
set -euo pipefail
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; PYTHON_BIN="${PYTHON_BIN:-${REPO_ROOT}/.venv/bin/python}"
DATA_ROOT="${DATA_ROOT:?set DATA_ROOT for staged/downloaded public data}"; CAMPAIGN_BASE="${CAMPAIGN_BASE:?set CAMPAIGN_BASE for persistent outputs}"
SAM31_REPO_ROOT="${SAM31_REPO_ROOT:-${REPO_ROOT}/external/sam3}"; SAM31_CHECKPOINT="${SAM31_CHECKPOINT:-${REPO_ROOT}/checkpoints/sam3.1/sam3.1_multiplex.pt}"
SLURM_PARTITION="${SLURM_PARTITION:?}"; SLURM_ACCOUNT="${SLURM_ACCOUNT:?}"; GPU_GRES="${GPU_GRES:-gpu:a40:1}"; NUM_WORKERS="${NUM_WORKERS:-32}"; SEED="${SEED:-20260909}"
mkdir -p "${CAMPAIGN_BASE}/"{evaluation,train,submission-logs} "${CAMPAIGN_BASE}/evaluation/slurm_logs" "${CAMPAIGN_BASE}/train/slurm_logs"
array_end=$((NUM_WORKERS-1)); log_root="${CAMPAIGN_BASE}/submission-logs"; common="REPO_ROOT=${REPO_ROOT},PYTHON_BIN=${PYTHON_BIN},DATA_ROOT=${DATA_ROOT},SEED=${SEED}"
prep="$(sbatch --parsable --partition="${PREP_PARTITION:-${SLURM_PARTITION}}" --account="${SLURM_ACCOUNT}" --time="${PREP_TIME_LIMIT:-12:00:00}" --cpus-per-task=8 --mem="${PREP_MEMORY:-64G}" --output="${log_root}/prepare-%j.out" --error="${log_root}/prepare-%j.err" --export=ALL,${common} "${REPO_ROOT}/slurm/prepare_datasets.slurm")"
eval_root="${CAMPAIGN_BASE}/evaluation"; train_root="${CAMPAIGN_BASE}/train"
eval_list="$(sbatch --parsable --partition="${PREP_PARTITION:-${SLURM_PARTITION}}" --account="${SLURM_ACCOUNT}" --time=02:00:00 --cpus-per-task=8 --mem=64G --dependency="afterok:${prep}" --output="${eval_root}/slurm_logs/worklist-%j.out" --error="${eval_root}/slurm_logs/worklist-%j.err" --export=ALL,${common},CAMPAIGN_ROOT=${eval_root},SCOPE=evaluation "${REPO_ROOT}/slurm/build_worklist.slurm")"
train_list="$(sbatch --parsable --partition="${PREP_PARTITION:-${SLURM_PARTITION}}" --account="${SLURM_ACCOUNT}" --time=04:00:00 --cpus-per-task=8 --mem=96G --dependency="afterok:${prep}" --output="${train_root}/slurm_logs/worklist-%j.out" --error="${train_root}/slurm_logs/worklist-%j.err" --export=ALL,${common},CAMPAIGN_ROOT=${train_root},SCOPE=train "${REPO_ROOT}/slurm/build_worklist.slurm")"
worker_env="REPO_ROOT=${REPO_ROOT},PYTHON_BIN=${PYTHON_BIN},SAM31_REPO_ROOT=${SAM31_REPO_ROOT},SAM31_CHECKPOINT=${SAM31_CHECKPOINT},SHARD_COUNT=${NUM_WORKERS},PYTHON_RUNTIME_ARCHIVE=${PYTHON_RUNTIME_ARCHIVE:-}"
eval_array="$(sbatch --parsable --partition="${SLURM_PARTITION}" --account="${SLURM_ACCOUNT}" --gres="${GPU_GRES}" --time="${TIME_LIMIT:-12:00:00}" --cpus-per-task="${CPUS_PER_TASK:-16}" --mem="${MEMORY:-64G}" --array="0-${array_end}" --dependency="afterok:${eval_list}" --output="${eval_root}/slurm_logs/worker-%A_%a.out" --error="${eval_root}/slurm_logs/worker-%A_%a.err" --export=ALL,${worker_env},CAMPAIGN_ROOT=${eval_root} "${REPO_ROOT}/slurm/process_array.slurm")"
eval_export="$(sbatch --parsable --partition="${PREP_PARTITION:-${SLURM_PARTITION}}" --account="${SLURM_ACCOUNT}" --time=02:00:00 --cpus-per-task=4 --mem=48G --dependency="afterany:${eval_array}" --output="${eval_root}/slurm_logs/export-%j.out" --error="${eval_root}/slurm_logs/export-%j.err" --export=ALL,REPO_ROOT=${REPO_ROOT},PYTHON_BIN=${PYTHON_BIN},CAMPAIGN_ROOT=${eval_root} "${REPO_ROOT}/slurm/export.slurm")"
# Train is both lower priority and held until the evaluation array ends.
train_array="$(sbatch --parsable --partition="${SLURM_PARTITION}" --account="${SLURM_ACCOUNT}" --gres="${GPU_GRES}" --time="${TIME_LIMIT:-12:00:00}" --cpus-per-task="${CPUS_PER_TASK:-16}" --mem="${MEMORY:-64G}" --array="0-${array_end}" --nice="${TRAIN_NICE:-10000}" --dependency="afterok:${train_list},afterany:${eval_array}" --output="${train_root}/slurm_logs/worker-%A_%a.out" --error="${train_root}/slurm_logs/worker-%A_%a.err" --export=ALL,${worker_env},CAMPAIGN_ROOT=${train_root} "${REPO_ROOT}/slurm/process_array.slurm")"
train_export="$(sbatch --parsable --partition="${PREP_PARTITION:-${SLURM_PARTITION}}" --account="${SLURM_ACCOUNT}" --time=04:00:00 --cpus-per-task=4 --mem=64G --dependency="afterany:${train_array}" --output="${train_root}/slurm_logs/export-%j.out" --error="${train_root}/slurm_logs/export-%j.err" --export=ALL,REPO_ROOT=${REPO_ROOT},PYTHON_BIN=${PYTHON_BIN},CAMPAIGN_ROOT=${train_root} "${REPO_ROOT}/slurm/export.slurm")"
ledger="${CAMPAIGN_BASE}/submissions.txt"
printf '%s prep\n%s evaluation_worklist\n%s train_worklist\n%s evaluation_workers\n%s evaluation_export\n%s train_workers\n%s train_export\n' "${prep}" "${eval_list}" "${train_list}" "${eval_array}" "${eval_export}" "${train_array}" "${train_export}" | tee -a "${ledger}"
